"""Embed the repository license unchanged for the offline Agreement page."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    text = (ROOT / "LICENSE").read_text(encoding="utf-8")
    revision = hashlib.sha256(text.encode("utf-8")).hexdigest()
    output = (
        "// SPDX-License-Identifier: LicenseRef-FNCL-1.1 | Copyright (c) 2026 andre68723\n"
        "// Generated by tools/generate_license_agreement.py; edit LICENSE, not this file.\n"
        f"const LICENSE_AGREEMENT = {json.dumps({'revision': revision, 'text': text}, ensure_ascii=False, indent=2)};\n"
    )
    (ROOT / "components/webui/www/js/license-agreement.js").write_text(output, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
